sys_script_include.script:
var BusinessProcessAPI = Class.create();
BusinessProcessAPI.prototype = 
{
    initialize: function()
	{
    },

	business_process: null,

	GetBusinessProcess: function()
	{
		return this.business_process;
	},

	Validate: function(bDetailed)
	{
		return BusinessProcessValidate(this.business_process,bDetailed);
	},

/*
	GetProcessTable: function()
	{
		var strTable = 
	},
*/

	Error: function(vPayload)
	{
		Error(vPayload);
	},

	IsValidProcessRecord: function(grProcess)
	{
		if (IsValidRecord(grProcess) == false)
		{
			return false;
		}
		var strRecordClassName = grProcess.getRecordClassName();
		if (strRecordClassName.endsWith('_' + this.business_process.id) == false)
		{
			return false;
		}
		return true;
	},

	_IsUiActionVisible: function(grCurrent, strTransition)
	{
		if (this.IsValidProcessRecord(grCurrent) == false)
		{
			return false;
		}
		// get the id of the current state
		// check if this is a valid transition
		return true;
	}, 

	_UiActionTransition: function(grCurrent, strTransition)
	{
		if (this.IsValidProcessRecord(grCurrent) == false)
		{
			this.Error('Implementation error: _UiActionTransition() called with invalid current GlideRecord object!');
			return false;
		}

		//this.GetTransition(strTransition);

		var nNewState = 100;

		grCurrent.state = nNewState;
		grCurrent.update();
		RedirectToRecord(grCurrent);

		return true;
	},

	_BusinessRuleBeforeInsertOrUpdate: function(grCurrent, grPrevious)
	{
		if (this.IsValidProcessRecord(grCurrent) == false)
		{
			return false;
		}

		// A change is possible
		if (this.IsValidProcessRecord(grPrevious) == true)
		{
			var nOldState = GetIntegerValue(grPrevious.state);
			var nNewState = GetIntegerValue(grCurrent.state);			
			if (nOldState != nNewState)
			{
				this._StateChange(grCurrent,nOldState,nNewState);
			}
		}
		return true;
	},

	_StateChange: function(grProcess,nOldState,nNewState)
	{
		this.Log(grProcess, 'StateChange from nOldState '+nOldState+' to nNewState '+nNewState +'.');

		// is the state change valid?

		this.onStateChange(grProcess,nOldState,nNewState);

	},

	Log: function(grProcess, vPayload)
	{
		Log('BusinessProcessAPI: ' + this.type + ': ' + grProcess.number + ': ' + RenderValue(vPayload));
	},

	type: 'BusinessProcessAPI'
};
